package com.onlinelibrary.model;
public class Book {
 private long id; private String title,author,isbn,genre,publisher; private Integer publicationYear; private int totalQuantity,availableQuantity;
 public Book() {} public Book(long id,String title,String author,String isbn,String genre,String publisher,Integer publicationYear,int totalQuantity,int availableQuantity){this.id=id;this.title=title;this.author=author;this.isbn=isbn;this.genre=genre;this.publisher=publisher;this.publicationYear=publicationYear;this.totalQuantity=totalQuantity;this.availableQuantity=availableQuantity;}
 public long getId(){return id;} public void setId(long v){id=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getAuthor(){return author;} public void setAuthor(String v){author=v;} public String getIsbn(){return isbn;} public void setIsbn(String v){isbn=v;} public String getGenre(){return genre;} public void setGenre(String v){genre=v;} public String getPublisher(){return publisher;} public void setPublisher(String v){publisher=v;} public Integer getPublicationYear(){return publicationYear;} public void setPublicationYear(Integer v){publicationYear=v;} public int getTotalQuantity(){return totalQuantity;} public void setTotalQuantity(int v){totalQuantity=v;} public int getAvailableQuantity(){return availableQuantity;} public void setAvailableQuantity(int v){availableQuantity=v;}
}
